public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder builder = new StringBuilder();
    char[] chars = str.toCharArray();
    for (int i = 0; i < chars.length; i++) {
        char c = chars[i];
        if (c == '\\' && i < chars.length - 1) {
            char next = chars[i + 1];
            switch (next) {
                case '\\':
                    builder.append('\\');
                    break;
                case 'n':
                    builder.append('\n');
                    break;
                case 'r':
                    builder.append('\r');
                    break;
                case 'v':
                    builder.append('\v');
                    break;
                case 't':
                    builder.append('\t');
                    break;
                case 'f':
                    builder.append('\f');
                    break;
                case 'u':
                    // unicode escape
                    if (i < chars.length - 5) {
                        String hex = str.substring(i + 2, i + 6);
                        char[] chars2 = hex.toCharArray();
                        int val = Integer.parseInt(new String(chars2), 16);
                        builder.append((char) val);
                        i += 5;
                    } else {
                        throw new Exception("invalid unicode escape sequence");
                    }
                    break;
                default:
                    // if none of the above applies, the '\' is not an escape sequence and should be unescaped
                    builder.append(next);
                    break;
            }
            i++;
        } else {
            builder.append(c);
        }
    }
    return builder.toString();
}

